        CommentsConfiguration configuration = new CommentsConfiguration(existingComments);

        Map<String, List<String>> map = configuration.getAllComments();

        assertThat(map.size(), is(1));
        assertThat(map.get("path"), is(Arrays.asList("existingLine")));
    }

    @Test
    public void shouldReturnUnmodifiableMapWhenSettingCommentWithEmptyList() {
        commentsConfiguration = new CommentsConfiguration();
        commentsConfiguration.setComment("path", Collections.emptyList());

        Map<String, List<String>> map = commentsConfiguration.getAllComments();

        assertThat(map.size(), is(1));
        assertThat(map.get("path"), is(Collections.emptyList()));
    }
